void exercise1() {
	uint32_t toggle = 0;

	pl_lcd_init();
	pl_lcd_led_init();

	while (1) {
		// busy waiting
		volatile uint32_t j = 0;
		for (j; j < 100000; ++j) {
			__NOP(); // No operation
		}

		pl_lcd_led_set(toggle);

/* 		if (toggle) {
			GPIOA -> BSRR = 1 << 5; // LED on
			
		} else {
			GPIOA -> BRR = 1 << 5; // LED off
			
		} */

		if (toggle) {
			toggle = 0;
		} else {
			toggle = 1;
		}
	}
	
}

